{
  "name": "apex-api",
  "description": "Core backend services for the application",
  "type": "server",
  "profile": "apex-prod",
  "regions": [
    "us-east-1",
    "eu-west-1"
  ],
  "lambda": {
    "accelerate": true,
    "warm": true,
    "warm_rate": "5m",
    "warm_count": 10,
    "memory": 1024
  },
  "stages": {
    "production": {
      "domain": "api.apex-project.com"
    },
    "staging": {
      "domain": "stage-api.apex-project.com"
    },
    "development": {
      "domain": "dev-api.apex-project.com"
    }
  },
  "hooks": {
    "build": "npm run build",
    "predeploy": "npm test"
  },
  "proxy": {
    "command": "node dist/index.js",
    "timeout": 30,
    "listen_timeout": 20,
    "shutdown_timeout": 10,
    "backoff": {
      "min": 100,
      "max": 2000,
      "factor": 2,
      "attempts": 3,
      "jitter": true
    }
  },
  "error_pages": {
    "disable": false,
    "dir": "./public/errors",
    "variables": {
      "support_email": "support@apex-project.com",
      "color": "#ff0000"
    }
  },
  "cors": {
    "enable": true,
    "allowed_origins": [
      "https://app.apex-project.com"
    ],
    "allowed_methods": [
      "GET",
      "POST",
      "PUT",
      "DELETE"
    ],
    "allowed_headers": [
      "Content-Type",
      "Authorization"
    ],
    "exposed_headers": [
      "X-Request-ID"
    ],
    "max_age": 3600,
    "allowed_credentials": true
  },
  "actions": [
    {
      "name": "admin-email",
      "type": "email",
      "emails": [
        "admin@apex-project.com"
      ]
    }
  ],
  "alerts": [
    {
      "metric": "http.5xx",
      "statistic": "sum",
      "threshold": 5,
      "action": "admin-email",
      "period": "1m",
      "evaluation_periods": 3,
      "operator": ">",
      "namespace": "AWS/ApiGateway",
      "description": "High error rate detected"
    }
  ]
}

