{
  "jobs": [
    {
      "name": "build-and-deploy-job",
      "execute": [
        "npm install",
        "npm run build",
        "docker build -t my-app:latest ."
      ],
      "set-proxy": [
        "npm",
        "docker"
      ],
      "no-proxy-hosts": [
        "internal.registry.local",
        "10.0.0.1"
      ],
      "run-on": {
        "image": "node:18-alpine",
        "resources": {
          "cpu": "2.0",
          "memory": "4Gi"
        },
        "use": [
          "docker"
        ],
        "platform": "k8s"
      },
      "artifacts": [
        "dist/",
        "build/outputs/apk/"
      ],
      "caches": [
        {
          "key": "node-modules-cache",
          "path": "node_modules"
        }
      ],
      "max-execution-time": "30m",
      "post-process": {
        "git-ops": {
          "manifest": {
            "repo": "org/manifest-repo",
            "branch": "main"
          },
          "update": [
            "sed -i 's/tag:.*/tag: latest/' deployment.yaml"
          ],
          "with-artifacts": [
            "dist/config.json"
          ]
        }
      }
    }
  ],
  "on": {
    "push": {
      "branches": [
        "main",
        "develop"
      ],
      "tags": [
        "v*"
      ],
      "commit": {
        "message-contain": "[release]"
      }
    },
    "pull-request": {
      "branches": [
        "main"
      ],
      "types": [
        "opened",
        "synchronize"
      ]
    }
  },
  "environment": [
    {
      "name": "NODE_ENV",
      "value": "production",
      "branch": "main"
    },
    {
      "name": "API_URL",
      "value": "https://api.example.com"
    }
  ]
}

{
  "boundedContextName": "user-management",
  "moduleName": "user-profile",
  "moduleNames": "user-profiles",
  "aggregateName": "UserProfile",
  "version": "1.0.0",
  "hasOAuth": true,
  "hasTenant": true,
  "hasAuditing": true,
  "aggregateProperties": [
    {
      "name": "id",
      "type": "id",
      "primaryKey": true,
      "autoIncrement": true,
      "webComponent": {
        "type": "select"
      }
    },
    {
      "name": "emailAddress",
      "type": "varchar",
      "length": 255,
      "nullable": false,
      "index": "unique",
      "indexName": "idx_user_email",
      "example": "john.doe@example.com"
    },
    {
      "name": "accountStatus",
      "type": "enum",
      "enumOptions": [
        "active",
        "inactive",
        "suspended"
      ],
      "defaultValue": "active",
      "example": "active"
    },
    {
      "name": "bioDescription",
      "type": "text",
      "nullable": true,
      "example": "Software engineer from New York."
    },
    {
      "name": "accountBalance",
      "type": "decimal",
      "decimals": [
        12,
        2
      ],
      "webComponent": {
        "type": "grid-select-element"
      }
    },
    {
      "name": "roles",
      "type": "manyToMany",
      "relationship": {
        "type": "many-to-many",
        "singularName": "role",
        "aggregate": "UserRole",
        "modulePath": "iam/role",
        "packageName": "@aurora-ts/core",
        "isDenormalized": false,
        "pivot": {
          "aggregate": "UserRolePivot",
          "modulePath": "iam/role",
          "fileName": "user-roles"
        }
      }
    }
  ],
  "aggregateI18nProperties": [
    {
      "name": "displayName",
      "type": "varchar",
      "length": 100
    }
  ],
  "additionalApis": [
    {
      "path": "/profiles/search",
      "resolverType": "query",
      "httpMethod": "get"
    },
    {
      "path": "/profiles/update",
      "resolverType": "mutation",
      "httpMethod": "patch"
    }
  ]
}

